<template>
  <F7Page>
    <F7Navbar title="More" large :sliding="true" />

    <div class="p-4">
      <capacitor-google-map
        ref="mapRef"
        class="inline-block h-[400px] w-[275px]"
      ></capacitor-google-map>

      <button
        class="mt-4 rounded-lg bg-[#1f6df5] px-4 py-2 font-semibold text-white"
        @click="createMap()"
      >
        Create Map
      </button>
    </div>
  </F7Page>
</template>

<script setup lang="ts">
import { shallowRef, useTemplateRef } from "vue";
import { GoogleMap } from "@capacitor/google-maps";

const mapRef = useTemplateRef<HTMLElement>("mapRef");
const newMap = shallowRef<GoogleMap>();

async function createMap() {
  if (!mapRef.value) return;

  newMap.value = await GoogleMap.create({
    id: "my-cool-map",
    element: mapRef.value,
    apiKey: import.meta.env.VITE_GOOGLE_MAPS_API_KEY as string,
    config: {
      center: { lat: 33.6, lng: -117.9 },
      zoom: 8,
    },
  });
}
</script>
